import 'package:flutter/material.dart';
import '../models/match.dart';
import '../theme/app_theme.dart';
import 'logo.dart';
class MatchCard extends StatelessWidget { final FootballMatch match; final Map<String,String> selections; final VoidCallback onTap; const MatchCard({super.key,required this.match,required this.selections,required this.onTap});
  @override Widget build(BuildContext context){ final s=selections[match.number.toString()]??''; return Card(child:InkWell(borderRadius:BorderRadius.circular(18),onTap:onTap,child:Padding(padding:const EdgeInsets.all(14),child:Column(children:[Row(children:[Text('#${match.number}',style:const TextStyle(color:AppTheme.green,fontWeight:FontWeight.bold)),const SizedBox(width:8),Expanded(child:Text(match.league,style:TextStyle(color:Colors.white.withOpacity(.55),fontSize:12))),Text('${match.date} • ${match.time}',style:TextStyle(color:Colors.white.withOpacity(.6),fontSize:11))]),const SizedBox(height:14),Row(children:[Expanded(child:Column(children:[TeamLogo(name:match.home),const SizedBox(height:7),Text(match.home,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w700))])),const Padding(padding:EdgeInsets.symmetric(horizontal:8),child:Text('VS',style:TextStyle(color:Colors.white38,fontSize:11,fontWeight:FontWeight.bold))),Expanded(child:Column(children:[TeamLogo(name:match.away),const SizedBox(height:7),Text(match.away,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w700))]))]),const SizedBox(height:14),Row(children:['1','X','2'].map((x)=>Expanded(child:Padding(padding:const EdgeInsets.symmetric(horizontal:3),child:ChoiceChip(label:Center(child:Text(x,style:const TextStyle(fontWeight:FontWeight.bold))),selected:s.contains(x),onSelected:(_){ }))).toList()) )])))); }
}
